/* Rock formation update: when hit, plays a sound and bursts into 200 debris pieces. */
void rock_formation_update(DebrisMoby *m) {
    DebrisHit *hit;
    int i;
    int j;
    float s;

    hit = (DebrisHit *)MobyGetHitMessage(m, 0x10000, 0);
    m->hit_slot = 0xFF;
    if (hit != 0 && hit->force > 0.0f) {
        Moby_PlaySound(0, 0x10, (int)m);
        for (i = 0; i < 200; i++) {
            {
                Vec4 vel;
                Vec4 pos;
                Vec4 off;

                pos.q = 0;
                pos.f[0] = random_float_between(-1.0f, 1.0f);
                pos.f[1] = random_float_between(-1.0f, 1.0f);
                pos.f[2] = random_float_between(-1.0f, 1.0f);
                off.q = 0;
                vel.q = pos.q;
                s = random_float_between(-1.0f, 1.0f);
                s *= FastCos(m->rotz);
                off.f[0] = s;
                s = random_float_between(-0.3f, 0.3f);
                s *= FastSin(m->rotz);
                off.f[1] = s;
                off.f[2] = random_float_between(0.0f, 2.0f);
                pos.q = off.q;
                FastVecAdd(&pos, &pos, &m->pos);
                vec_scale_to_length(&vel, &vel, random_float_between(0.5f, 1.5f) * g_frame_time);
                s = random_float_between(0.5f, 1.0f) * 210000.0f;
                PartType22Spawn(&pos, &vel, 0x5F787878, 0x181818, s, scale_ticks(rand_range(30, 90)));
            }
        }
        for (j = 0; j < 40; j++) {
            DebrisColors colors;
            Vec4 vel;
            Vec4 pos;
            Vec4 off;

            colors = rock_formation_debris_colors;
            pos.q = 0;
            pos.f[0] = random_float_between(-1.0f, 1.0f);
            pos.f[1] = random_float_between(-1.0f, 1.0f);
            pos.f[2] = random_float_between(-1.0f, 1.0f);
            off.q = 0;
            vel.q = pos.q;
            s = random_float_between(-1.2f, 1.2f);
            s *= FastCos(m->rotz);
            off.f[0] = s;
            s = random_float_between(-0.4f, 0.4f);
            s *= FastSin(m->rotz);
            off.f[1] = s;
            off.f[2] = random_float_between(0.5f, 2.0f);
            pos.q = off.q;
            FastVecAdd(&pos, &pos, &m->pos);
            vec_scale_to_length(&vel, &vel, random_float_between(1.0f, 5.0f) * g_frame_time);
            ((void (*)(void *, void *, int, float, int, float, float, float, int))spawn_debris_moby)(&pos, &vel, colors.c[random_integer_below(3)], random_float_between(0.04f, 0.09f),
                              rand_range(60, 180), 1.0f, 1.0f, 0.75f, 0);
        }
        SetDeathBits(m, 0, -1);
        DeleteMoby(m);
    }
}
