/* Oscillating spinner: swings its angle between -1 and 1 and turns the moby to match. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/l01/unclassified_002f9810.c, FUN_L01_002f9bf0. */
void fan_update(SwayMoby *m) {
    SwayVars *v;
    CollQuery q;

    v = m->pvars;
    if (m->state == 0) {
        copy_hero_moby_field_38(m);
        m->state = 1;
        v->sway = random_float_between(-1.0f, 1.0f);
        v->dir = (func_001160D8() & 1) ? 1.0f : -1.0f;
    }
    q.moby = m;
    q.flags = 0x10001;
    q.x1c = 0;
    clear_u64_value(&q);
    q.x20 = 0;
    coll_sphere_mobys(m->pos, 0x10, m, &q, 1.2f);
    if (v->dir == v->sway) {
        if (fast_dec_timer(&v->timer)) {
            v->dir = -v->dir;
            v->timer = scale_ticks(0x5A);
        }
    }
    v->sway += g_frame_time * 4.0f * v->dir;
    if (v->sway > 1.0f) {
        v->sway = 1.0f;
    }
    if (v->sway < -1.0f) {
        v->sway = -1.0f;
    }
    m->rotz = FastAddRots(m->rotz, g_frame_time * -12.566371f * v->sway);
}
