/* Spawns a beam moby (0x2D2) from owner between two points, colored, with random rotation and two glow sprites.
   Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/l01/unclassified_002f9810.c, FUN_L01_002fa068. */
char *spawn_colored_half_scale_moby(int owner, void *pos, void *target, int color) {
    Vy p;
    Vy t;
    char *m;
    char *v;
    Vy *pp;
    Vy *tp;

    pp = &p;
    tp = &t;
    p = *(Vy *)pos;
    t = *(Vy *)target;
    m = CreateMoby(0x2D2);
    if (m != 0) {
        v = ((char *)((Moby *)m)->pvars);
        *(int *)(v + 0x10) = owner;
        m[0x30] = 0x7F;
        ((Moby *)m)->draw_dist = 0x7F;
        m[0x31] = 1;
        ((Moby *)m)->scale = ((Moby *)m)->scale * 0.5f;
        set_moby_color(m, 0x7F, 0x7F, 0x7F);
        ((Moby *)m)->rot.x = random_angle_radians();
        ((Moby *)m)->rot.y = random_angle_radians();
        ((Moby *)m)->rot.z = random_angle_radians();
        qcopy(m + 0x10, pp);
        qcopy(v, tp);
        *(int *)(v + 0x14) = color;
        spawn_source_attached_fading_effect_particle(m, 0x2F00007F, color, -1, 210000.0f);
        spawn_source_attached_fading_effect_particle(m, 0x4F004F7F, *(int *)(v + 0x14), -1, 115500.0f);
        ((void (*)(void *))moby_build_matrix)(m);
    }
    return m;
}
