/* Per-frame update of a falling drop: integrates its velocity, tests it against the world and spawns its impact effect. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/l01/unclassified_002f9810.c, FUN_L01_002fa4c0. */
void update_birdbot_projectile(DropMoby *m) {
    DropVars *v;
    Vec4 *pos;
    Vec4 prev;
    DropProbe probe;
    Vec4 tmp;
    float a;
    float b;
    float zero;
    float one;
    float ten;
    float half;

    v = m->vars;
    pos = &m->pos;
    qcopy(&prev, pos);
    zero = 0.0f;
    one = 1.0f;
    ten = 10.0f;
    a = multiply_global_factor(ten);
    b = multiply_global_factor(ten);
    b = b * multiply_global_factor(ten);
    v->vel.f[2] -= (a * zero + one) * 2.0f / b;
    FastVecAdd(pos, pos, &v->vel);
    if (m->pos.f[0] < zero || m->pos.f[1] < zero || m->pos.f[2] < zero
        || vec_distance_xy(pos, camera_pos) > 64.0f) {
        DeleteMoby(m);
        return;
    }
    probe.owner = m;
    probe.flags = 0x10001;
    probe.scale = one;
    probe.count = 1;
    qcopy(&probe.dir, &v->vel);
    probe.dir.f[2] = one;
    probe.dir.f[3] = 5627.9248f;
    probe.b28 = 1;
    probe.b29 = 1;
    probe.id = m->hA6;
    if (fast_dec_timer(v->sound) != 0) {
        tmp = m->pos;
        spawn_explosion_effects(m, &tmp, 0, 0.5f, zero);
        DeleteMoby(m);
    } else if (coll_line(&prev, pos, 0, v->coll, &probe) != 0) {
        qcopy(pos, novalis_coll_hit_point);
        tmp = m->pos;
        spawn_explosion_effects(m, &tmp, 0, 0.5f, zero);
        DeleteMoby(m);
    } else {
        half = 0.5f;
        if (coll_sphere_mobys_r(half, pos, 0x10, v->coll, &probe) != 0) {
            tmp = m->pos;
            spawn_explosion_effects(m, &tmp, 0, half, zero);
            DeleteMoby(m);
        }
    }
}
