/* Flying explosive blob: drag, gravity and spin; explodes on hit or timeout, leaves smoke. */
void update_explosive_moby(struct Moby *m) {
    BlobVars *v;
    int hit;
    int i;
    int n;
    int c;
    int alpha;
    int grey;
    float s;
    u8 *p;
    u8 *q;

    v = (BlobVars *)m->pvars;
    if (random_integer_below(2)) {
        AddDrawCallback(draw_moby_offset_textured_quad, m);
    }
    FastVecAdd(&m->pos, &m->pos, v);
    if (FastAbsF(v->vel.x) > *(float *)&explosive_moby_drag_min_speed * frame_scale) {
        v->vel.x *= (*(float *)&explosive_moby_drag - 1.0f) * frame_scale + 1.0f;
    }
    if (FastAbsF(v->vel.y) > *(float *)&explosive_moby_drag_min_speed * frame_scale) {
        v->vel.y *= (*(float *)&explosive_moby_drag - 1.0f) * frame_scale + 1.0f;
    }
    if (v->vel.z > 0.0f) {
        v->vel.z *= (*(float *)&explosive_moby_drag - 1.0f) * frame_scale + 1.0f;
    }
    v->vel.z -= *(float *)&explosive_moby_gravity * g_frame_time_sq;
    m->rot.x = FastAddRots(m->rot.x, v->spin.x);
    m->rot.y = FastAddRots(m->rot.y, v->spin.y);
    m->rot.z = FastAddRots(m->rot.z, v->spin.z);
    if (m->pos.x < 2.0f || m->pos.x > 1021.0f || m->pos.y < 2.0f || m->pos.y > 1021.0f ||
        m->pos.z < 2.0f || m->pos.z > 1021.0f) {
        DeleteMoby(m);
        return;
    }
    hit = coll_sphere(2.0f, &m->pos, 0, (void *)v->owner);
    if (fast_dec_timer(&v->timer) || hit) {
        if (hit) {
            if (novalis_coll_hit.have_normal) {
                vec_reflect(v, v, &novalis_coll_hit.normal);
            } else {
                clear_u64_value(v);
            }
        }
        spawn_explosion(m, v, &m->pos, 0.0f, 0.0f, 0x14, 3, 4, 4.0f, 2.0f, 100000.0f, 3.0f, 0, 15.0f, 1, 1,
                         -1, 0);
        DeleteMoby(m);
        return;
    }
    s = random_float_between(0.5f, 1.5f) * 210000.0f;
    PartType21Spawn(&m->pos, novalis_zero_vec, 0x4F007FFF, 0x1FFFFFFF, s,
               rand_range(scale_ticks(10), scale_ticks(20)), 1);
    alpha = 0x60000000;
    for (i = 0; i < 2; i++) {
        n = random_integer_below(6);
        if (random_integer_below(2)) {
            n = -n;
        }
        s = random_float_between(40000.0f, 100000.0f);
        c = rand_range(0x30, 0xFF);
        grey = (c << 8) | 0x60000000;
        p = PartType23Spawn(&m->pos, 0.025f, 1.0f, 1.0f, n, novalis_zero_vec, s, c | ((c << 16) | grey));
        if (p != 0) {
            p[3] = 0x44;
            q = p + 0x20;
            *(s16 *)(p + 0xA) = scale_ticks(60);
            *(s32 *)(q + 4) = 2;
            q[0xA] = alpha >> 24;
            q[0xB] = p[0xA];
        }
    }
}
